-- =====================================================================
-- ATHOSlife — conteúdo do banco em inglês e espanhol (2026-10-09)
--
-- O app já fala pt/en/es, mas conquistas, exercícios, receitas e 110
-- suplementos de marca vinham só em português. Esta migração:
--   1. cria `traducoes jsonb` em conquistas_catalogo, exercicios_catalogo
--      e receitas_cozinha  ->  {"en": {...}, "es": {...}}
--   2. cria `conteudo_traducoes jsonb` em receitas_cozinha (o modo de
--      preparo é conteúdo pago: NÃO ganha GRANT, só sai pela RPC)
--   3. troca receitas_conteudo_liberado() por (p_idioma text default
--      'pt-BR'): devolve o conteúdo traduzido quando existir
--   4. preenche nome_en/nome_es dos suplementos de marca (marca não muda)
--
-- Sem tradução, o app cai no português (nada quebra). Pode rodar de novo:
-- tudo é "if not exists" / update idempotente.
-- =====================================================================

begin;

alter table public.conquistas_catalogo add column if not exists traducoes jsonb not null default '{}'::jsonb;
alter table public.exercicios_catalogo add column if not exists traducoes jsonb not null default '{}'::jsonb;
alter table public.receitas_cozinha add column if not exists traducoes jsonb not null default '{}'::jsonb;
alter table public.receitas_cozinha add column if not exists conteudo_traducoes jsonb not null default '{}'::jsonb;

-- receitas_cozinha usa GRANT por coluna (conteudo fica de fora): libera só
-- título/subtítulo traduzidos. conteudo_traducoes continua sem GRANT.
grant select (traducoes) on public.receitas_cozinha to authenticated;


-- 1. Conquistas (26)
update public.conquistas_catalogo set traducoes = '{"en": {"nome": "First Step", "descricao": "Open the app for the first time"}, "es": {"nome": "Primer Paso", "descricao": "Abrir la app por primera vez"}}'::jsonb where id = 'primeiro_passo';
update public.conquistas_catalogo set traducoes = '{"en": {"nome": "Finding the Rhythm", "descricao": "3 days in a row in the app"}, "es": {"nome": "Agarrando Ritmo", "descricao": "3 días seguidos en la app"}}'::jsonb where id = 'pegando_ritmo';
update public.conquistas_catalogo set traducoes = '{"en": {"nome": "One Strong Week", "descricao": "7 days in a row"}, "es": {"nome": "Una Semana Fuerte", "descricao": "7 días seguidos"}}'::jsonb where id = 'uma_semana_forte';
update public.conquistas_catalogo set traducoes = '{"en": {"nome": "Two Weeks Unstoppable", "descricao": "14 days in a row"}, "es": {"nome": "Dos Semanas Imparable", "descricao": "14 días seguidos"}}'::jsonb where id = 'duas_semanas';
update public.conquistas_catalogo set traducoes = '{"en": {"nome": "30 Days Legendary", "descricao": "30 days in a row"}, "es": {"nome": "30 Días Legendario", "descricao": "30 días seguidos"}}'::jsonb where id = 'trinta_dias';
update public.conquistas_catalogo set traducoes = '{"en": {"nome": "100 Days Elite", "descricao": "100 days in a row"}, "es": {"nome": "100 Días Élite", "descricao": "100 días seguidos"}}'::jsonb where id = 'cem_dias';
