-- 2. Exercícios (100): nome sempre; músculos e passos quando existem em pt
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Hip Thrust", "musculos_trabalhados": "Mainly works the glutes, with help from the hamstrings.", "como_executar": ["Rest your upper back on the bench, bend your knees and place the bar over your hips.", "Lift your hips by squeezing your glutes and lower with control."]}, "es": {"nome": "Hip Thrust (Elevación de Cadera)", "musculos_trabalhados": "Trabaja principalmente los glúteos, con participación de los isquiotibiales.", "como_executar": ["Apoya la espalda en el banco, flexiona las rodillas y coloca la barra sobre la cadera.", "Eleva la cadera contrayendo los glúteos y baja con control."]}}'::jsonb where id = 'bacfce4d-4552-478b-b5e7-1b9c8587b3ad';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Cable Glute Kickback", "musculos_trabalhados": "Mainly works the glutes, with help from the hamstrings.", "como_executar": ["Hold the support, keep your torso firm and the cable attached to your ankle.", "Push your leg back squeezing the glute and return slowly."]}, "es": {"nome": "Patada de Glúteo en Polea", "musculos_trabalhados": "Trabaja principalmente los glúteos, con participación de los isquiotibiales.", "como_executar": ["Sujeta el apoyo, mantén el tronco firme y el cable sujeto al tobillo.", "Lleva la pierna hacia atrás contrayendo el glúteo y vuelve despacio."]}}'::jsonb where id = 'dbaf3046-e3db-4324-870b-055ca047efac';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Hip Abduction Machine", "musculos_trabalhados": "Works the glutes, mainly the side of the hips.", "como_executar": ["Sit with your back supported and your knees together against the pads.", "Open your knees without lifting your feet and return with control."]}, "es": {"nome": "Máquina Abductora", "musculos_trabalhados": "Trabaja los glúteos, principalmente la zona lateral de la cadera.", "como_executar": ["Siéntate con la espalda apoyada y las rodillas juntas contra los apoyos.", "Abre las rodillas sin despegar los pies y vuelve con control."]}}'::jsonb where id = '2b71d16a-ac37-42a4-82e9-28db491e34c7';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Seated Calf Raise", "musculos_trabalhados": "Mainly works the soleus, in the lower calves.", "como_executar": ["Sit with your knees under the pad and the balls of your feet on the platform.", "Raise your heels as high as you can and lower with control."]}, "es": {"nome": "Elevación de Gemelos Sentado", "musculos_trabalhados": "Trabaja principalmente el sóleo, en la parte inferior de los gemelos.", "como_executar": ["Siéntate con las rodillas bajo el apoyo y la parte delantera de los pies en la plataforma.", "Eleva los talones lo más que puedas y baja con control."]}}'::jsonb where id = '99a3e296-db46-4f35-bac6-913b2336ce95';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Standing Calf Raise", "musculos_trabalhados": "Mainly works the gastrocnemius, in the upper calves.", "como_executar": ["Rest your shoulders under the pads, put the balls of your feet on the platform and keep your body upright.", "Rise onto your toes, squeeze your calves and lower slowly."]}, "es": {"nome": "Elevación de Gemelos de Pie", "musculos_trabalhados": "Trabaja principalmente el gastrocnemio, en la parte superior de los gemelos.", "como_executar": ["Apoya los hombros, coloca la parte delantera de los pies en la plataforma y mantén el cuerpo erguido.", "Sube de puntillas, contrae los gemelos y vuelve despacio."]}}'::jsonb where id = '3675f04c-c4f0-439e-8d9a-a7f7c32f1837';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Deadlift", "musculos_trabalhados": "Works the glutes, hamstrings, lower back and back.", "como_executar": ["Feet under the bar, hips back, knees bent and spine neutral.", "Extend your hips and knees, keep the bar close and lower with control."]}, "es": {"nome": "Peso Muerto", "musculos_trabalhados": "Trabaja glúteos, isquiotibiales, zona lumbar y espalda.", "como_executar": ["Pies bajo la barra, cadera atrás, rodillas flexionadas y columna neutra.", "Extiende cadera y rodillas, mantén la barra cerca y baja con control."]}}'::jsonb where id = 'e83131af-7e06-41aa-b501-89a66bea42a3';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Dumbbell Lunge", "musculos_trabalhados": "Works the quads and glutes, with help from the hamstrings.", "como_executar": ["Stand holding the dumbbells at your sides and keep your torso upright.", "Step forward, bend your knees and push off the floor to come back."]}, "es": {"nome": "Zancada con Mancuernas", "musculos_trabalhados": "Trabaja cuádriceps y glúteos, con participación de los isquiotibiales.", "como_executar": ["Ponte de pie, sujeta las mancuernas a los lados del cuerpo y mantén el tronco erguido.", "Da un paso al frente, flexiona las rodillas y empuja el suelo para volver."]}}'::jsonb where id = 'e22423bf-a357-4178-836b-24ebc6f2478c';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Bulgarian Split Squat", "musculos_trabalhados": "Works the quads and glutes, focusing on one leg at a time.", "como_executar": ["Rest one foot on the bench behind you and keep the other firm on the floor.", "Lower keeping your front knee aligned and come up with control."]}, "es": {"nome": "Sentadilla Búlgara", "musculos_trabalhados": "Trabaja cuádriceps y glúteos, con mayor énfasis en una pierna a la vez.", "como_executar": ["Apoya un pie en el banco detrás de ti y mantén el otro firme en el suelo.", "Baja manteniendo la rodilla delantera alineada y sube con control."]}}'::jsonb where id = '844b6110-a07a-47c2-82dd-7b8b7aabe9be';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Hack Squat", "musculos_trabalhados": "Works the quads and glutes, with help from the hamstrings.", "como_executar": ["Rest your back and shoulders on the pads, put your feet on the platform and keep your spine neutral.", "Lower with control and push the platform without locking your knees."]}, "es": {"nome": "Sentadilla Hack", "musculos_trabalhados": "Trabaja cuádriceps y glúteos, con participación de los isquiotibiales.", "como_executar": ["Apoya espalda y hombros, coloca los pies en la plataforma y mantén la columna neutra.", "Baja con control y empuja la plataforma sin bloquear las rodillas."]}}'::jsonb where id = 'aa7ec230-7181-4acb-b6d7-103db9534c14';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Leg Extension", "musculos_trabalhados": "Mainly works the quads, at the front of the thighs.", "como_executar": ["Sit with your back supported and your shins behind the machine pad.", "Extend your knees without locking them and lower the weight with control."]}, "es": {"nome": "Extensión de Piernas en Máquina", "musculos_trabalhados": "Trabaja principalmente los cuádriceps, en la parte delantera de los muslos.", "como_executar": ["Siéntate con la espalda apoyada y las espinillas detrás del apoyo de la máquina.", "Extiende las rodillas sin bloquearlas y baja el peso con control."]}}'::jsonb where id = '97b1a40b-a231-4104-b820-c032eed32b44';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Lying Leg Curl", "musculos_trabalhados": "Works the hamstrings, with help from the calves.", "como_executar": ["Lie face down, line up your knees and place your ankles under the pad.", "Bend your knees bringing your heels toward your glutes and return."]}, "es": {"nome": "Curl Femoral Acostado", "musculos_trabalhados": "Trabaja los isquiotibiales, con participación de los gemelos.", "como_executar": ["Acuéstate boca abajo, alinea las rodillas y coloca los tobillos bajo el apoyo.", "Flexiona las rodillas llevando los talones hacia los glúteos y vuelve."]}}'::jsonb where id = '283bd9c7-e1e1-4e18-b5b1-6bec4902e2b6';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Seated Leg Curl", "musculos_trabalhados": "Works the hamstrings, with help from the calves.", "como_executar": ["Sit with your back supported, legs straight and ankles on the pad.", "Pull the pad back with your heels and return slowly."]}, "es": {"nome": "Curl Femoral Sentado", "musculos_trabalhados": "Trabaja los isquiotibiales, con participación de los gemelos.", "como_executar": ["Siéntate con la espalda apoyada, piernas extendidas y tobillos en el apoyo.", "Lleva el apoyo hacia atrás con los talones y vuelve despacio."]}}'::jsonb where id = '2f14c090-7baf-471f-9a8f-c4b6aedb3c06';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Seated Cable Row", "musculos_trabalhados": "Works the back, mainly the mid-back and lats.", "como_executar": ["Sit with your knees slightly bent, torso upright and arms straight.", "Pull the handle to your belly, squeezing your shoulder blades, and return."]}, "es": {"nome": "Remo Bajo en Polea", "musculos_trabalhados": "Trabaja la espalda, principalmente la zona media y el dorsal ancho.", "como_executar": ["Siéntate con las rodillas ligeramente flexionadas, tronco erguido y brazos extendidos.", "Tira del agarre hasta el abdomen, juntando las escápulas, y vuelve."]}}'::jsonb where id = 'eb16d89e-af46-42da-b4cd-3b7ad582cb64';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Barbell Bent-Over Row", "musculos_trabalhados": "Works the back, focusing on the lats and mid-back.", "como_executar": ["Hinge your torso forward, keep your spine neutral and the bar below your shoulders.", "Pull the bar toward your belly, keeping your elbows close."]}, "es": {"nome": "Remo Inclinado con Barra", "musculos_trabalhados": "Trabaja la espalda, con foco en el dorsal ancho y la zona media.", "como_executar": ["Inclina el tronco, mantén la columna neutra y la barra por debajo de los hombros.", "Tira de la barra hacia el abdomen, manteniendo los codos cerca."]}}'::jsonb where id = 'bcb5ed8c-d416-4279-8ecd-4b7f869ed689';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "One-Arm Dumbbell Row", "musculos_trabalhados": "Works the lats, rhomboids and rear shoulders.", "como_executar": ["Rest one hand and one knee on the bench, spine neutral and dumbbell hanging.", "Pull the dumbbell toward your ribs and lower with control."]}, "es": {"nome": "Remo a Una Mano con Mancuerna", "musculos_trabalhados": "Trabaja el dorsal ancho, los romboides y la parte posterior del hombro.", "como_executar": ["Apoya una mano y una rodilla en el banco, columna neutra y mancuerna colgando.", "Tira de la mancuerna hacia las costillas y baja con control."]}}'::jsonb where id = 'c19b1047-6ed2-41b7-9729-1a0548eec071';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Push-up", "musculos_trabalhados": "Works the chest, shoulders and triceps using body weight.", "como_executar": ["Hands on the floor, arms straight and body in a straight line.", "Lower your chest with control and push the floor to come back up."]}, "es": {"nome": "Flexión de Brazos", "musculos_trabalhados": "Trabaja pecho, hombros y tríceps con el peso del cuerpo.", "como_executar": ["Manos apoyadas en el suelo, brazos extendidos y cuerpo alineado.", "Baja el pecho con control y empuja el suelo para volver."]}}'::jsonb where id = '3888683c-0da0-4ca9-892e-ebc39d3881f6';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Machine Chest Press", "musculos_trabalhados": "Works the chest, with help from the shoulders and triceps.", "como_executar": ["Sit with your back supported and the handles close to your chest.", "Push the handles forward without locking your elbows and return."]}, "es": {"nome": "Press de Pecho en Máquina", "musculos_trabalhados": "Trabaja el pectoral, con participación de hombros y tríceps.", "como_executar": ["Siéntate con la espalda apoyada y los agarres cerca del pecho.", "Empuja los agarres hacia adelante sin bloquear los codos y vuelve."]}}'::jsonb where id = 'f6582476-a45c-44ba-805e-7b05150a5bff';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Lat Pulldown", "musculos_trabalhados": "Works the back, mainly the lats and biceps.", "como_executar": ["Hold the bar with a wide grip, torso upright and arms straight.", "Pull the bar to your chest, squeezing your shoulder blades."]}, "es": {"nome": "Jalón al Pecho", "musculos_trabalhados": "Trabaja la espalda, principalmente el dorsal ancho y los bíceps.", "como_executar": ["Sujeta la barra con agarre abierto, tronco erguido y brazos extendidos.", "Tira de la barra hasta el pecho, juntando las escápulas."]}}'::jsonb where id = '93d46f26-10ff-4947-b865-434ef5c59976';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Flat Dumbbell Fly", "musculos_trabalhados": "Works the chest, focusing on the inner part.", "como_executar": ["Lie on the bench, dumbbells above your chest and elbows slightly bent.", "Open your arms until you feel the stretch and return by squeezing your chest."]}, "es": {"nome": "Aperturas Planas con Mancuernas", "musculos_trabalhados": "Trabaja el pectoral, con foco en la parte interna.", "como_executar": ["Acuéstate en el banco, mancuernas sobre el pecho y codos ligeramente flexionados.", "Abre los brazos hasta sentir el estiramiento y vuelve contrayendo el pectoral."]}}'::jsonb where id = '383ff5dd-071b-40c5-a6ca-592d976f6b32';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Cable Crossover", "musculos_trabalhados": "Works the chest, focusing on the squeeze.", "como_executar": ["Stand between the pulleys, torso slightly forward and arms open.", "Pull the handles forward and bring your hands together, squeezing your chest."]}, "es": {"nome": "Cruce de Poleas", "musculos_trabalhados": "Trabaja el pectoral, con foco en la contracción muscular.", "como_executar": ["Colócate entre las poleas, tronco ligeramente inclinado y brazos abiertos.", "Lleva los agarres hacia adelante y junta las manos, contrayendo el pectoral."]}}'::jsonb where id = '94ad2444-3de2-45e4-b551-ce87b4ba40ae';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Pec Deck", "musculos_trabalhados": "Isolates the chest, focusing on the inner part.", "como_executar": ["Sit with your back supported and arms open on the machine.", "Bring your arms together in front of you, squeezing your chest."]}, "es": {"nome": "Pec Deck (Contractora)", "musculos_trabalhados": "Aísla el pectoral, con foco en la parte interna.", "como_executar": ["Siéntate con la espalda apoyada y los brazos abiertos en la máquina.", "Junta los brazos frente al cuerpo, contrayendo el pectoral."]}}'::jsonb where id = '8223bf14-1083-49af-aa59-059a311799df';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Barbell Bench Press", "musculos_trabalhados": "Works the middle of the chest, with help from the shoulders and triceps.", "como_executar": ["Lie on the bench, feet firm on the floor and hands on the bar a bit wider than your shoulders.", "Press the bar up until your arms are straight, keeping the movement controlled."]}, "es": {"nome": "Press de Banca con Barra", "musculos_trabalhados": "Trabaja la parte central del pectoral, con participación de hombros y tríceps.", "como_executar": ["Acuéstate en el banco, pies firmes en el suelo y manos en la barra un poco más abiertas que los hombros.", "Empuja la barra hacia arriba hasta extender los brazos, controlando el movimiento."]}}'::jsonb where id = '597b969d-d01a-4464-b23b-eb3bc97477c0';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Incline Dumbbell Press", "musculos_trabalhados": "Works the upper chest, shoulders and triceps.", "como_executar": ["Dumbbells close to your chest, bench inclined and elbows bent.", "Press the dumbbells up until your arms are straight, bringing them together without clashing."]}, "es": {"nome": "Press Inclinado con Mancuernas", "musculos_trabalhados": "Trabaja la parte superior del pectoral, hombros y tríceps.", "como_executar": ["Mancuernas cerca del pecho, banco inclinado y codos flexionados.", "Empuja las mancuernas hacia arriba hasta extender los brazos, acercándolas sin chocarlas."]}}'::jsonb where id = '554a1456-ed91-4f58-99d9-92c6d342968f';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Decline Bench Press", "musculos_trabalhados": "Works the lower chest, with help from the shoulders and triceps.", "como_executar": ["Lie on the decline bench, feet secured and bar lined up above your chest.", "Lower the bar under control to your chest and press it up."]}, "es": {"nome": "Press Declinado", "musculos_trabalhados": "Trabaja la parte inferior del pectoral, con participación de hombros y tríceps.", "como_executar": ["Acuéstate en el banco declinado, pies firmes y barra alineada sobre el pecho.", "Baja la barra de forma controlada hasta el pecho y empújala hacia arriba."]}}'::jsonb where id = 'ce0062b5-3b6a-4ae0-b520-d692765dccbc';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Dumbbell Reverse Fly", "musculos_trabalhados": "Works the rear shoulders and upper back.", "como_executar": ["Hinge your torso forward, keep your spine neutral and the dumbbells below your shoulders.", "Raise your arms out to the sides and return slowly, without swinging."]}, "es": {"nome": "Aperturas Invertidas con Mancuernas", "musculos_trabalhados": "Trabaja la parte posterior de los hombros y la zona superior de la espalda.", "como_executar": ["Inclina el tronco, mantén la columna neutra y las mancuernas bajo los hombros.", "Abre los brazos hacia los lados y vuelve despacio, sin impulso."]}}'::jsonb where id = 'bcc739cf-1d8b-4366-a963-83314d4e9733';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Face Pull", "musculos_trabalhados": "Works the rear shoulders and upper back muscles.", "como_executar": ["Hold the rope at face height, arms straight and torso firm.", "Pull the rope toward your face, flaring your elbows, and return."]}, "es": {"nome": "Face Pull", "musculos_trabalhados": "Trabaja la parte posterior de los hombros y los músculos de la parte superior de la espalda.", "como_executar": ["Sujeta la cuerda a la altura de la cara, brazos extendidos y tronco firme.", "Tira de la cuerda hacia la cara, abriendo los codos, y vuelve."]}}'::jsonb where id = 'db1a13f9-5569-46c4-b00e-158290933160';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Dumbbell Shrug", "musculos_trabalhados": "Mainly works the traps, in the upper back.", "como_executar": ["Stand with dumbbells at your sides and shoulders relaxed.", "Raise your shoulders toward your ears and lower with control."]}, "es": {"nome": "Encogimiento con Mancuernas", "musculos_trabalhados": "Trabaja principalmente el trapecio, en la zona superior de la espalda.", "como_executar": ["Ponte de pie con las mancuernas a los lados y los hombros relajados.", "Eleva los hombros hacia las orejas y baja con control."]}}'::jsonb where id = 'a15125ea-856b-441d-81c4-e18bfb46591e';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Dumbbell Shoulder Press", "musculos_trabalhados": "Works the shoulders, with help from the triceps.", "como_executar": ["Dumbbells at shoulder height, elbows bent and torso firm.", "Press the dumbbells up without locking your elbows and return."]}, "es": {"nome": "Press de Hombros con Mancuernas", "musculos_trabalhados": "Trabaja los hombros, con participación de los tríceps.", "como_executar": ["Mancuernas a la altura de los hombros, codos flexionados y tronco firme.", "Empuja las mancuernas hacia arriba sin bloquear los codos y vuelve."]}}'::jsonb where id = 'd1e2c51b-d2e6-40b1-bedd-215080767392';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Dumbbell Lateral Raise", "musculos_trabalhados": "Mainly works the side of the shoulders.", "como_executar": ["Stand with dumbbells at your sides and elbows slightly bent.", "Raise your arms to shoulder height and lower with control."]}, "es": {"nome": "Elevación Lateral con Mancuernas", "musculos_trabalhados": "Trabaja principalmente la porción lateral de los hombros.", "como_executar": ["Ponte de pie, mancuernas a los lados y codos ligeramente flexionados.", "Eleva los brazos hasta la altura de los hombros y baja con control."]}}'::jsonb where id = 'f55d01e1-9fe0-48b5-a720-25479402c4e0';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Front Raise", "musculos_trabalhados": "Mainly works the front of the shoulders.", "como_executar": ["Dumbbells in front of your thighs, arms straight and torso firm.", "Raise your arms in front to shoulder height and return slowly."]}, "es": {"nome": "Elevación Frontal", "musculos_trabalhados": "Trabaja principalmente la parte anterior de los hombros.", "como_executar": ["Mancuernas frente a los muslos, brazos extendidos y tronco firme.", "Eleva los brazos al frente hasta la altura de los hombros y vuelve despacio."]}}'::jsonb where id = '4506bd70-f48c-4aec-af7d-4215d3ab6490';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Back Extension (Roman Chair)", "musculos_trabalhados": "Works the lower back, spinal erectors and glutes.", "como_executar": ["Rest your hips on the bench, keep your torso tilted and your spine neutral.", "Raise your torso until your body is in line and return slowly."]}, "es": {"nome": "Extensión Lumbar (Banco Romano)", "musculos_trabalhados": "Trabaja la zona lumbar, los erectores de la columna y los glúteos.", "como_executar": ["Apoya la cadera en el banco, mantén el tronco inclinado y la columna neutra.", "Eleva el tronco hasta alinear el cuerpo y vuelve lentamente."]}}'::jsonb where id = 'de80981c-55a0-4177-9a0b-d0cceff1c754';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Barbell Back Squat", "musculos_trabalhados": "Works the quads, glutes and hamstrings.", "como_executar": ["Bar resting on your shoulders, feet apart and spine neutral.", "Lower by bending hips and knees and come up pushing the floor."]}, "es": {"nome": "Sentadilla Libre con Barra", "musculos_trabalhados": "Trabaja cuádriceps, glúteos e isquiotibiales.", "como_executar": ["Barra apoyada en los hombros, pies separados y columna neutra.", "Baja flexionando cadera y rodillas y sube empujando el suelo."]}}'::jsonb where id = 'a6a37e75-11be-46ce-b68f-362d9a42087b';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "45° Leg Press", "musculos_trabalhados": "Works the quads, glutes and hamstrings.", "como_executar": ["Rest your back, put your feet on the platform and bend your knees.", "Push the platform without locking your knees and return with control."]}, "es": {"nome": "Prensa de Piernas 45°", "musculos_trabalhados": "Trabaja cuádriceps, glúteos e isquiotibiales.", "como_executar": ["Apoya la espalda, coloca los pies en la plataforma y flexiona las rodillas.", "Empuja la plataforma sin bloquear las rodillas y vuelve con control."]}}'::jsonb where id = 'd9d69cb5-e036-4b0b-bf03-ffcd06e3551c';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Pull-up", "musculos_trabalhados": "Works the back, mainly the lats, plus the biceps.", "como_executar": ["Hold the bar with a wide grip, arms straight and body steady.", "Pull yourself up until your chest nears the bar and lower with control."]}, "es": {"nome": "Dominadas", "musculos_trabalhados": "Trabaja la espalda, principalmente el dorsal ancho, además de los bíceps.", "como_executar": ["Sujeta la barra con agarre abierto, brazos extendidos y cuerpo estable.", "Tira del cuerpo hasta acercar el pecho a la barra y baja con control."]}}'::jsonb where id = '672e0908-b28b-4f56-b0f2-d50097795628';
update public.exercicios_catalogo set traducoes = '{"en": {"nome": "Machine Pulldown", "musculos_trabalhados": "Works the back, focusing on the lats and mid-back.", "como_executar": ["Sit with your back supported and arms straight on the handles.", "Pull the handles down, bringing your elbows toward your torso."]}, "es": {"nome": "Jalón en Máquina", "musculos_trabalhados": "Trabaja la espalda, con foco en el dorsal ancho y la zona media.", "como_executar": ["Siéntate con la espalda apoyada y los brazos extendidos en los agarres.", "Tira de los agarres hacia abajo, acercando los codos al tronco."]}}'::jsonb where id = '689c4ffb-aaef-42be-b735-e7dfd1e7b799';
