-- 3. Receitas (25): vitrine em traducoes, modo de preparo em conteudo_traducoes
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Chicken & Chickpea Power Salad", "subtitulo": "A full plate that''s light and keeps hunger away"}, "es": {"titulo": "Ensalada Power de Pollo y Garbanzos", "subtitulo": "Plato lleno, ligero y que quita el hambre"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: A real salad, not a garnish: lots of greens, chicken and chickpeas to keep you going until your next meal.\n\nINGREDIENTS (1 serving):\n- Greens as much as you like (lettuce, arugula, spinach)\n- 100g shredded chicken\n- 50g cooked chickpeas\n- 1 tomato and 1/2 grated carrot\n- A drizzle of olive oil (5g) and lemon\n\nPREPARATION:\n1. Wash and dry the greens well — wet leaves don''t hold dressing.\n2. Dice the tomato and grate the carrot.\n3. If the chicken is cold, warm it quickly in a pan without oil.\n\nTO SERVE:\n1. Cover the plate with the greens — the more, the better.\n2. Spread the chicken and chickpeas on top.\n3. Add the tomato and carrot.\n4. Dress with olive oil, lemon and salt right before eating.\n\nLIFE''S TIP: Eat the greens first, before the protein. You''ll feel full sooner.", "es": "SOBRE EL PLATO: Una ensalada de verdad, no de adorno: mucha hoja, pollo y garbanzos para aguantar hasta la próxima comida.\n\nINGREDIENTES (1 porción):\n- Hojas a gusto (lechuga, rúcula, espinaca)\n- 100g de pollo desmenuzado\n- 50g de garbanzos cocidos\n- 1 tomate y 1/2 zanahoria rallada\n- Un chorrito de aceite de oliva (5g) y limón\n\nPREPARACIÓN:\n1. Lava y seca bien las hojas — la hoja mojada no retiene el aliño.\n2. Corta el tomate en cubos y ralla la zanahoria.\n3. Si el pollo está frío, caliéntalo rápido en una sartén sin aceite.\n\nMONTAJE:\n1. Cubre el plato con las hojas — cuantas más, mejor.\n2. Reparte el pollo y los garbanzos por encima.\n3. Añade el tomate y la zanahoria.\n4. Aliña con aceite, limón y sal justo al comer.\n\nCONSEJO DE LIFE: Come primero las hojas, antes de la proteína. La saciedad llega antes."}'::jsonb
where id = '53c7e715-8af8-4f34-be65-03f992290d5c';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Protein Overnight Oats", "subtitulo": "Breakfast ready the night before"}, "es": {"titulo": "Overnight Oats Proteicos", "subtitulo": "Desayuno listo desde la noche anterior"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: You make it at night and wake up to breakfast ready: creamy, cold and packed with protein. Zero excuses in the morning.\n\nINGREDIENTS (1 serving):\n- 40g rolled oats\n- 1 scoop whey (30g)\n- 150ml milk or plant-based drink\n- 1/2 banana, sliced\n- Cinnamon to taste\n\nPREPARATION:\n1. In a jar with a lid, mix the oats, whey and milk until no powder is left.\n2. Cover and refrigerate overnight (at least 6 hours).\n\nTO SERVE:\n1. In the morning, stir well — if it''s too thick, add a splash of milk.\n2. Top with the banana slices and sprinkle with cinnamon.\n3. Eat it cold, straight from the jar.\n\nLIFE''S TIP: Make two jars at once. Tomorrow morning you''ll thank me.", "es": "SOBRE EL PLATO: Lo preparas por la noche y amaneces con el desayuno listo: cremoso, frío y con proteína. Cero excusas por la mañana.\n\nINGREDIENTES (1 porción):\n- 40g de avena en hojuelas\n- 1 scoop de whey (30g)\n- 150ml de leche o bebida vegetal\n- 1/2 plátano en rodajas\n- Canela a gusto\n\nPREPARACIÓN:\n1. En un frasco con tapa, mezcla la avena, el whey y la leche hasta que no quede polvo.\n2. Tapa y deja en la nevera de un día para otro (mínimo 6 horas).\n\nMONTAJE:\n1. Por la mañana, remueve bien — si está muy espeso, añade un poco de leche.\n2. Cubre con las rodajas de plátano y espolvorea canela.\n3. Cómelo frío, directo del frasco.\n\nCONSEJO DE LIFE: Haz dos frascos de una vez. Mañana por la mañana me lo agradecerás."}'::jsonb
where id = '8c4a27f1-6398-49a1-a36f-1e081a1b0fef';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Thermogenic Soup", "subtitulo": "Hot, light and with ginger for the evening"}, "es": {"titulo": "Sopa Termogénica", "subtitulo": "Caliente, ligera y con jengibre para la noche"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: A hearty chicken broth with ginger and pepper: it warms you up, comforts and doesn''t weigh you down. Perfect for the evening.\n\nINGREDIENTS (1 serving):\n- 100g shredded chicken\n- 1 tomato and 1/2 onion\n- 1 garlic clove\n- Grated ginger and pepper to taste\n- Vegetables to taste (zucchini, carrot)\n\nPREPARATION:\n1. Chop the onion, garlic, tomato and vegetables.\n2. Sauté the garlic, onion and ginger in a pot.\n3. Add the tomato and vegetables and stir for 2 minutes.\n4. Cover with water, season and cook for 15 minutes.\n5. Add the chicken and simmer for another 5 minutes.\n\nTO SERVE:\n1. Serve piping hot in a deep bowl.\n2. Finish with a pinch of pepper on top.\n\nLIFE''S TIP: Ginger and pepper give it that nice warmth. Want more broth? Just add more water — it barely changes the calories.", "es": "SOBRE EL PLATO: Un caldo sustancioso de pollo con jengibre y pimienta: calienta, reconforta y no pesa. Perfecta para la noche.\n\nINGREDIENTES (1 porción):\n- 100g de pollo desmenuzado\n- 1 tomate y 1/2 cebolla\n- 1 diente de ajo\n- Jengibre rallado y pimienta a gusto\n- Verduras a gusto (calabacín, zanahoria)\n\nPREPARACIÓN:\n1. Pica la cebolla, el ajo, el tomate y las verduras.\n2. Sofríe el ajo, la cebolla y el jengibre en una olla.\n3. Añade el tomate y las verduras y remueve 2 minutos.\n4. Cubre con agua, sazona y cocina 15 minutos.\n5. Agrega el pollo y deja hervir 5 minutos más.\n\nMONTAJE:\n1. Sirve bien caliente en un tazón hondo.\n2. Termina con una pizca de pimienta por encima.\n\nCONSEJO DE LIFE: El jengibre y la pimienta dan ese calorcito rico. ¿Quieres más caldo? Solo añade agua — casi no cambia las calorías."}'::jsonb
where id = 'b74b6990-dba1-423a-941a-1f30bc8e9f1b';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Baked Veggie Omelet", "subtitulo": "High-protein and practical for the whole week"}, "es": {"titulo": "Tortilla al Horno con Verduras", "subtitulo": "Proteica y práctica para toda la semana"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: Make it once and eat all week: a tall, soft omelet full of vegetables. Real protein for breakfast or a snack.\n\nINGREDIENTS (2 servings):\n- 4 eggs\n- 2 egg whites\n- 1 cup chopped vegetables (tomato, spinach, onion)\n- Salt, oregano and pepper\n\nPREPARATION:\n1. Preheat the oven to 180°C (350°F) and grease a small baking dish.\n2. Beat the eggs and egg whites with the seasonings.\n3. Stir in the chopped vegetables.\n4. Pour into the dish and bake for 20 minutes, until set in the center.\n\nTO SERVE:\n1. Wait 5 minutes before unmolding — that way it won''t break.\n2. Cut into 2 pieces (1 per serving).\n3. Serve warm or store in a container in the fridge.\n\nLIFE''S TIP: Take it to work and eat it cold — it''s great that way.", "es": "SOBRE EL PLATO: La haces una vez y comes toda la semana: tortilla alta, suave y llena de verduras. Proteína de verdad en el desayuno o la merienda.\n\nINGREDIENTES (2 porciones):\n- 4 huevos\n- 2 claras\n- 1 taza de verduras picadas (tomate, espinaca, cebolla)\n- Sal, orégano y pimienta\n\nPREPARACIÓN:\n1. Precalienta el horno a 180°C y engrasa un molde pequeño.\n2. Bate los huevos y las claras con los condimentos.\n3. Mezcla las verduras picadas.\n4. Vierte en el molde y hornea 20 minutos, hasta que cuaje en el centro.\n\nMONTAJE:\n1. Espera 5 minutos antes de desmoldar — así no se rompe.\n2. Corta en 2 pedazos (1 por porción).\n3. Sirve caliente o guarda en un recipiente en la nevera.\n\nCONSEJO DE LIFE: Llévala al trabajo y cómela fría, que queda muy rica."}'::jsonb
where id = '58e3a881-38f9-41c8-b140-a22c95f95f95';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Zucchini Spaghetti with Chicken", "subtitulo": "Looks like pasta, light like veggies"}, "es": {"titulo": "Espagueti de Calabacín con Pollo", "subtitulo": "Cara de pasta, ligereza de verdura"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: Zucchini strips stand in for pasta, with a fraction of the calories. Golden chicken, tomato and basil on top.\n\nINGREDIENTS (1 serving):\n- 150g diced chicken\n- 1 large zucchini cut into thin strips\n- 1 chopped tomato and garlic\n- A drizzle of olive oil (5g)\n- Basil and salt\n\nPREPARATION:\n1. Cut the zucchini into thin strips with a peeler or spiralizer.\n2. Brown the chicken with the garlic in the olive oil.\n3. Add the tomato and cook until it forms a light sauce.\n4. Add the zucchini and stir for just 2 minutes.\n\nTO SERVE:\n1. Twirl the \"spaghetti\" with a fork and place it in the center of the plate.\n2. Spread the chicken and sauce on top.\n3. Finish with basil leaves.\n\nLIFE''S TIP: Don''t overcook the zucchini — 2 minutes is enough, or it goes limp.", "es": "SOBRE EL PLATO: El calabacín en tiras hace de pasta, con una fracción de las calorías. Pollo dorado, tomate y albahaca por encima.\n\nINGREDIENTES (1 porción):\n- 150g de pollo en cubos\n- 1 calabacín grande en tiras finas\n- 1 tomate picado y ajo\n- Un chorrito de aceite de oliva (5g)\n- Albahaca y sal\n\nPREPARACIÓN:\n1. Haz tiras finas de calabacín con un pelador o espiralizador.\n2. Dora el pollo con el ajo en el aceite.\n3. Añade el tomate y sofríe hasta formar una salsita.\n4. Agrega el calabacín y remueve solo 2 minutos.\n\nMONTAJE:\n1. Enrolla el \"espagueti\" con un tenedor y colócalo en el centro del plato.\n2. Reparte el pollo y la salsa por encima.\n3. Termina con hojas de albahaca.\n\nCONSEJO DE LIFE: No cocines demasiado el calabacín — 2 minutos bastan, si no se ablanda."}'::jsonb
where id = 'ea221b4b-fb2f-4ecd-9d44-4f66481cd88b';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Grilled Chicken & Broccoli Bowl", "subtitulo": "The gym-goer''s classic, done right"}, "es": {"titulo": "Bowl de Pollo a la Plancha con Brócoli", "subtitulo": "El clásico de quien entrena, bien hecho"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: The basics that work: juicy grilled chicken, fluffy rice and broccoli cooked just right. Protein and carbs in the right amounts to build muscle.\n\nINGREDIENTS (1 serving):\n- 150g grilled chicken breast\n- 150g cooked white rice\n- 100g steamed broccoli\n- A drizzle of olive oil (5g)\n- Salt, garlic and pepper\n\nPREPARATION:\n1. Season the chicken with salt, garlic and pepper.\n2. Grill until golden on both sides and let it rest for 2 minutes.\n3. Steam the broccoli for 5 minutes (it stays green and firm).\n4. Warm up the rice.\n\nTO SERVE:\n1. Rice at the bottom of the bowl.\n2. Sliced chicken on one side, broccoli on the other.\n3. Finish with the drizzle of olive oil.\n\nLIFE''S TIP: Swap white rice for brown rice and you''ll stay full longer.", "es": "SOBRE EL PLATO: Lo básico que funciona: pollo a la plancha jugoso, arroz suelto y brócoli en su punto. Proteína y carbohidratos en la medida justa para construir músculo.\n\nINGREDIENTES (1 porción):\n- 150g de pechuga de pollo a la plancha\n- 150g de arroz blanco cocido\n- 100g de brócoli al vapor\n- Un chorrito de aceite de oliva (5g)\n- Sal, ajo y pimienta\n\nPREPARACIÓN:\n1. Sazona el pollo con sal, ajo y pimienta.\n2. Cocínalo a la plancha hasta dorar por ambos lados y déjalo reposar 2 minutos.\n3. Cocina el brócoli al vapor 5 minutos (queda verde y firme).\n4. Calienta el arroz.\n\nMONTAJE:\n1. Arroz en la base del bowl.\n2. Pollo en lonchas de un lado, brócoli del otro.\n3. Termina con el chorrito de aceite.\n\nCONSEJO DE LIFE: Cambia el arroz blanco por integral y aguantarás el hambre más tiempo."}'::jsonb
where id = 'd05386a4-72ad-45c3-9d99-f9de6b1ee43e';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Creamy Chicken Wrap", "subtitulo": "Ready in 10 minutes and full of protein"}, "es": {"titulo": "Wrap Cremoso de Pollo", "subtitulo": "Listo en 10 minutos y lleno de proteína"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: For when you''re hungry and short on time: a tortilla crispy outside, creamy chicken inside. 10 minutes and it''s in your hand.\n\nINGREDIENTS (1 serving):\n- 1 whole-wheat tortilla\n- 120g shredded chicken\n- 2 tablespoons light cream cheese\n- Greens and tomato\n- Salt and pepper\n\nPREPARATION:\n1. Season the chicken with salt and pepper (warm it if it''s cold).\n2. Slice the tomato and set the greens aside.\n\nTO SERVE:\n1. Spread the cream cheese on the tortilla.\n2. Lay the chicken, greens and tomato in a strip down the middle.\n3. Fold in the ends and roll it up tightly.\n4. Sear in a pan without oil, 1 minute per side (optional).\n5. Cut diagonally to serve.\n\nLIFE''S TIP: Searing it in the pan makes it crispy and keeps the wrap from opening.", "es": "SOBRE EL PLATO: Para cuando aprieta el hambre y hay poco tiempo: tortilla crujiente por fuera, pollo cremoso por dentro. 10 minutos y lo tienes en la mano.\n\nINGREDIENTES (1 porción):\n- 1 tortilla integral\n- 120g de pollo desmenuzado\n- 2 cucharadas de queso crema light\n- Hojas y tomate\n- Sal y pimienta\n\nPREPARACIÓN:\n1. Sazona el pollo con sal y pimienta (caliéntalo si está frío).\n2. Corta el tomate en rodajas y separa las hojas.\n\nMONTAJE:\n1. Unta el queso crema en la tortilla.\n2. Reparte el pollo, las hojas y el tomate en una franja en el centro.\n3. Dobla los extremos y enrolla bien apretado.\n4. Séllalo en la sartén sin aceite, 1 minuto por lado (opcional).\n5. Córtalo en diagonal para servir.\n\nCONSEJO DE LIFE: Sellarlo en la sartén lo deja crujiente y el wrap no se abre."}'::jsonb
where id = '8ec672bb-e950-43a3-a47d-12059e04df00';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Healthy Banana Cinnamon Pancakes", "subtitulo": "Breakfast that feels like dessert"}, "es": {"titulo": "Panqueques Fit de Plátano con Canela", "subtitulo": "Desayuno con cara de postre"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: Sweet, soft and full of energy, with no white flour. The banana sweetens and the oats add body.\n\nINGREDIENTS (1 serving):\n- 1 mashed banana\n- 2 eggs\n- 40g oats\n- 1 scoop whey (optional)\n- Cinnamon\n\nPREPARATION:\n1. Mash the banana well and mix it with the eggs.\n2. Add the oats (and the whey, if using) until it forms a batter.\n3. Heat a non-stick pan over low heat.\n4. Pour small portions and brown for 2 minutes per side.\n\nTO SERVE:\n1. Stack the pancakes on the plate.\n2. Sprinkle cinnamon on top.\n\nLIFE''S TIP: Low heat and patience. A good pancake is never rushed.", "es": "SOBRE EL PLATO: Dulces, suaves y llenos de energía, sin harina blanca. El plátano endulza y la avena da cuerpo.\n\nINGREDIENTES (1 porción):\n- 1 plátano machacado\n- 2 huevos\n- 40g de avena\n- 1 scoop de whey (opcional)\n- Canela\n\nPREPARACIÓN:\n1. Machaca bien el plátano y mézclalo con los huevos.\n2. Añade la avena (y el whey, si lo usas) hasta formar una masa.\n3. Calienta una sartén antiadherente a fuego bajo.\n4. Vierte porciones pequeñas y dora 2 minutos por lado.\n\nMONTAJE:\n1. Apila los panqueques en el plato.\n2. Espolvorea canela por encima.\n\nCONSEJO DE LIFE: Fuego bajo y paciencia. Un buen panqueque no tiene prisa."}'::jsonb
where id = 'c324cba4-b48b-4910-b3ff-e6d89789e0aa';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Garlic Pasta with Tuna", "subtitulo": "Cheap, quick and high in protein"}, "es": {"titulo": "Pasta al Ajo con Atún", "subtitulo": "Barata, rápida y proteica"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: An end-of-the-month dish that still delivers real protein: garlic golden in olive oil, tomato and tuna coating the pasta.\n\nINGREDIENTS (1 serving):\n- 80g pasta (dry weight)\n- 1 can tuna, drained\n- 1 chopped tomato and garlic\n- A drizzle of olive oil (10g)\n- Parsley and salt\n\nPREPARATION:\n1. Cook the pasta al dente and save half a ladle of the cooking water.\n2. Brown the garlic in the olive oil and add the tomato.\n3. Add the tuna and heat through.\n4. Toss in the pasta and the saved water until creamy.\n\nTO SERVE:\n1. Twirl the pasta in the center of the plate.\n2. Finish with chopped parsley.\n\nLIFE''S TIP: The pasta water is the secret to a creamy sauce without cream.", "es": "SOBRE EL PLATO: Un plato de fin de mes que aun así da proteína de verdad: ajo dorado en aceite, tomate y atún envolviendo la pasta.\n\nINGREDIENTES (1 porción):\n- 80g de pasta (peso en seco)\n- 1 lata de atún escurrido\n- 1 tomate picado y ajo\n- Un chorrito de aceite de oliva (10g)\n- Perejil y sal\n\nPREPARACIÓN:\n1. Cocina la pasta al dente y guarda medio cucharón del agua.\n2. Dora el ajo en el aceite y añade el tomate.\n3. Agrega el atún y calienta.\n4. Mezcla la pasta con el agua reservada hasta que quede cremosa.\n\nMONTAJE:\n1. Enrolla la pasta en el centro del plato.\n2. Termina con perejil picado.\n\nCONSEJO DE LIFE: El agua de la pasta es el secreto de una salsa cremosa sin nata."}'::jsonb
where id = '4ff0ddea-506b-4736-adaf-b86c191b0605';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Rustic Sweet Potato with Beef", "subtitulo": "Fuel for people who train hard"}, "es": {"titulo": "Batata Rústica con Carne", "subtitulo": "Combustible de quien entrena fuerte"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: Sweet potato roasted with the skin on, golden outside and soft inside, with well-seasoned ground beef. Quality carbs and dense protein.\n\nINGREDIENTS (1 serving):\n- 200g sweet potato with skin, diced\n- 150g lean ground beef\n- 1/2 onion and garlic\n- Tomato and seasonings\n- Salt and pepper\n\nPREPARATION:\n1. Wash the potato well and cut it into medium cubes, skin on.\n2. Season with salt and pepper and roast at 200°C (400°F) for 25 to 30 minutes (or 20 in the air fryer), until golden.\n3. Meanwhile, sauté the onion and garlic, add the beef and let it brown.\n4. Drain the fat, add the tomato and season well.\n\nTO SERVE:\n1. Place the potato cubes on the plate.\n2. Top with the ground beef.\n3. Finish with fresh herbs, if you have them.\n\nLIFE''S TIP: Drain the fat from the beef after browning. It cuts the excess without losing protein.", "es": "SOBRE EL PLATO: Batata asada con piel, dorada por fuera y suave por dentro, con carne molida bien sazonada. Carbohidratos de calidad y proteína densa.\n\nINGREDIENTES (1 porción):\n- 200g de batata con piel, en cubos\n- 150g de carne molida magra\n- 1/2 cebolla y ajo\n- Tomate y condimentos\n- Sal y pimienta\n\nPREPARACIÓN:\n1. Lava bien la batata y córtala en cubos medianos, con piel.\n2. Sazona con sal y pimienta y hornea a 200°C de 25 a 30 minutos (o 20 en la freidora de aire), hasta dorar.\n3. Mientras tanto, sofríe la cebolla y el ajo, añade la carne y deja que se dore.\n4. Escurre la grasa, agrega el tomate y sazona bien.\n\nMONTAJE:\n1. Coloca los cubos de batata en el plato.\n2. Cubre con la carne molida.\n3. Termina con hierbas frescas, si tienes.\n\nCONSEJO DE LIFE: Escurre la grasa de la carne después de dorarla. Quitas el exceso sin perder proteína."}'::jsonb
where id = '591977f1-4c23-4c18-9f1d-8ef49f8c86d7';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Mediterranean Chickpea Bowl", "subtitulo": "Plant protein that keeps you full"}, "es": {"titulo": "Bowl Mediterráneo de Garbanzos", "subtitulo": "Proteína vegetal que sacia"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: Hearty, colorful and 100% plant-based: chickpeas with cumin, fresh salad and lemon. Proof that meat-free food keeps you going.\n\nINGREDIENTS (1 serving):\n- 150g cooked chickpeas\n- 100g brown rice\n- Tomato, cucumber and red onion\n- A drizzle of olive oil (10g) and lemon\n- Cumin and salt\n\nPREPARATION:\n1. Season the chickpeas with cumin, olive oil and salt.\n2. Brown them in a pan for 5 minutes, until crispy.\n3. Dice the tomato, cucumber and red onion into small cubes.\n\nTO SERVE:\n1. Brown rice at the bottom of the bowl.\n2. Chickpeas on one side, salad on the other.\n3. Finish with a squeeze of lemon on top.\n\nLIFE''S TIP: Browning the chickpeas first changes everything — they get crispy like a snack.", "es": "SOBRE EL PLATO: Abundante, colorido y 100% vegetal: garbanzos con comino, ensalada fresca y limón. La prueba de que la comida sin carne sacia.\n\nINGREDIENTES (1 porción):\n- 150g de garbanzos cocidos\n- 100g de arroz integral\n- Tomate, pepino y cebolla morada\n- Un chorrito de aceite de oliva (10g) y limón\n- Comino y sal\n\nPREPARACIÓN:\n1. Sazona los garbanzos con comino, aceite y sal.\n2. Dóralos en una sartén 5 minutos, hasta que queden crujientes.\n3. Pica el tomate, el pepino y la cebolla morada en cubos pequeños.\n\nMONTAJE:\n1. Arroz integral en la base del bowl.\n2. Garbanzos de un lado, ensalada del otro.\n3. Termina con limón exprimido por encima.\n\nCONSEJO DE LIFE: Dorar los garbanzos antes lo cambia todo — quedan crujientes como un snack."}'::jsonb
where id = 'f894afa1-6ea4-4e72-83f6-be132d19c9be';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Golden Soy Sauce Tofu with Sesame", "subtitulo": "Golden crust and lots of flavor"}, "es": {"titulo": "Tofu Dorado en Salsa de Soja con Sésamo", "subtitulo": "Costrita dorada y mucho sabor"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: Nobody turns down well-seasoned tofu: golden cubes in soy sauce, vegetables cooked just right and sesame on top.\n\nINGREDIENTS (1 serving):\n- 150g firm tofu, cubed\n- Vegetables to taste (bell pepper, zucchini)\n- Soy sauce and garlic\n- A drizzle of olive oil (5g)\n- Sesame seeds\n\nPREPARATION:\n1. Pat the tofu dry with paper towels.\n2. Season with soy sauce and garlic and let it sit for 5 minutes.\n3. Brown the cubes in the olive oil until a crust forms.\n4. Quickly sauté the vegetables, keeping them crunchy.\n\nTO SERVE:\n1. Vegetables at the bottom of the plate.\n2. Golden tofu on top.\n3. Finish with sesame seeds.\n\nLIFE''S TIP: Wet tofu steams instead of browning. Drying it well is the secret.", "es": "SOBRE EL PLATO: Nadie rechaza un tofu bien sazonado: cubos dorados en salsa de soja, verduras en su punto y sésamo por encima.\n\nINGREDIENTES (1 porción):\n- 150g de tofu firme en cubos\n- Verduras a gusto (pimiento, calabacín)\n- Salsa de soja y ajo\n- Un chorrito de aceite de oliva (5g)\n- Sésamo\n\nPREPARACIÓN:\n1. Seca bien el tofu con papel de cocina.\n2. Sazona con salsa de soja y ajo y deja reposar 5 minutos.\n3. Dora los cubos en el aceite hasta que formen costra.\n4. Saltea las verduras rápido, que queden crujientes.\n\nMONTAJE:\n1. Verduras en el fondo del plato.\n2. Tofu dorado por encima.\n3. Termina con sésamo.\n\nCONSEJO DE LIFE: El tofu húmedo se cuece en vez de dorarse. Secarlo bien es el secreto."}'::jsonb
where id = '01810d66-8212-49f0-abdc-783973213fe8';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Creamy Cumin Lentils", "subtitulo": "The vegan rice-and-beans, upgraded"}, "es": {"titulo": "Lentejas Cremosas al Comino", "subtitulo": "El arroz con frijoles vegano, potenciado"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: Comfort food that nourishes: creamy lentils with cumin and cilantro over fluffy rice.\n\nINGREDIENTS (1 serving):\n- 100g cooked lentils\n- 100g cooked rice\n- 1/2 onion and garlic\n- Tomato and cumin\n- Salt and cilantro\n\nPREPARATION:\n1. Sauté the onion and garlic.\n2. Add the tomato and cumin and stir for 2 minutes.\n3. Add the lentils and a little water.\n4. Cook, mashing some of the lentils, until creamy.\n\nTO SERVE:\n1. Rice on the plate.\n2. Creamy lentils on top or on the side.\n3. Finish with chopped cilantro.\n\nLIFE''S TIP: Lentils and rice together make a complete protein. An unbeatable pair.", "es": "SOBRE EL PLATO: Comida reconfortante que nutre: lentejas cremosas con comino y cilantro sobre arroz suelto.\n\nINGREDIENTES (1 porción):\n- 100g de lentejas cocidas\n- 100g de arroz cocido\n- 1/2 cebolla y ajo\n- Tomate y comino\n- Sal y cilantro\n\nPREPARACIÓN:\n1. Sofríe la cebolla y el ajo.\n2. Añade el tomate y el comino y remueve 2 minutos.\n3. Agrega las lentejas y un poco de agua.\n4. Cocina aplastando algunas lentejas hasta que quede cremoso.\n\nMONTAJE:\n1. Arroz en el plato.\n2. Lentejas cremosas por encima o al lado.\n3. Termina con cilantro picado.\n\nCONSEJO DE LIFE: Lentejas con arroz forman una proteína completa. Una pareja imbatible."}'::jsonb
where id = '549d7ee3-07ae-44ec-85b2-a45bde50f789';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Vegan Banana Pancakes", "subtitulo": "No eggs, no milk, and they still hold together"}, "es": {"titulo": "Panqueques Veganos de Plátano", "subtitulo": "Sin huevo ni leche, y se mantienen unidos"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: A simple, tasty vegan breakfast: ripe banana does the egg''s job.\n\nINGREDIENTS (1 serving):\n- 1 ripe banana\n- 40g oats\n- 100ml plant-based drink\n- Cinnamon and baking powder (1 pinch)\n\nPREPARATION:\n1. Mash the banana and mix it with the plant-based drink.\n2. Add the oats, cinnamon and baking powder.\n3. Let it rest for 5 minutes to thicken.\n4. Brown in a non-stick pan, 2 minutes per side.\n\nTO SERVE:\n1. Stack the pancakes on the plate.\n2. Sprinkle cinnamon on top.\n\nLIFE''S TIP: The riper the banana, the sweeter it is and the better it binds.", "es": "SOBRE EL PLATO: Un desayuno vegano, simple y rico: el plátano maduro hace el papel del huevo.\n\nINGREDIENTES (1 porción):\n- 1 plátano maduro\n- 40g de avena\n- 100ml de bebida vegetal\n- Canela y polvo de hornear (1 pizca)\n\nPREPARACIÓN:\n1. Machaca el plátano y mézclalo con la bebida vegetal.\n2. Añade la avena, la canela y el polvo de hornear.\n3. Deja reposar 5 minutos para que espese.\n4. Dora en sartén antiadherente, 2 minutos por lado.\n\nMONTAJE:\n1. Apila los panqueques en el plato.\n2. Espolvorea canela por encima.\n\nCONSEJO DE LIFE: Cuanto más maduro el plátano, más dulce y mejor liga."}'::jsonb
where id = '7b8235c2-475b-4b24-a54e-4f9b02d93ea9';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Banana Ice Cream with Cocoa & Peanut", "subtitulo": "Kills the sugar craving without the crash"}, "es": {"titulo": "Helado de Plátano con Cacao y Maní", "subtitulo": "Calma el antojo dulce sin el bajón"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: A sugar craving isn''t weakness — it''s your body asking for quick energy. This creamy banana ice cream with cocoa and peanut butter satisfies it without sabotage.\n\nINGREDIENTS (1 serving):\n- 1 ripe frozen banana\n- 1 tablespoon 100% cocoa (10g)\n- 1 tablespoon peanut butter (15g)\n- Cinnamon to taste\n\nPREPARATION:\n1. Slice the banana and freeze it (at least 4 hours).\n2. Blend in a food processor until creamy.\n3. Add the cocoa and peanut butter and blend until smooth.\n\nTO SERVE:\n1. Put it in a bowl.\n2. Sprinkle with cinnamon and eat right away, like ice cream.\n\nLIFE''S TIP: This one really kills the craving, and tomorrow you won''t wake up beating yourself up. One step at a time.", "es": "SOBRE EL PLATO: Las ganas de dulce no son debilidad — es el cuerpo pidiendo energía rápida. Este helado cremoso de plátano con cacao y maní calma el antojo sin sabotearte.\n\nINGREDIENTES (1 porción):\n- 1 plátano maduro congelado\n- 1 cucharada de cacao 100% (10g)\n- 1 cucharada de mantequilla de maní (15g)\n- Canela a gusto\n\nPREPARACIÓN:\n1. Corta el plátano en rodajas y congélalo (mínimo 4 horas).\n2. Tritúralo en el procesador hasta que quede cremoso.\n3. Añade el cacao y la mantequilla de maní y tritura hasta que quede liso.\n\nMONTAJE:\n1. Ponlo en un tazón.\n2. Espolvorea canela y cómelo al momento, como helado.\n\nCONSEJO DE LIFE: Este sí calma el antojo de verdad, y mañana no te levantas culpándote. Un paso a la vez."}'::jsonb
where id = 'e77c3426-8e65-4137-911a-c00bf3b7acc7';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Smoked Paprika Popcorn", "subtitulo": "The swap for late-night junk food"}, "es": {"titulo": "Palomitas Ahumadas con Pimentón", "subtitulo": "El cambio para el picoteo de la noche"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: For binge-watching hunger without raiding the pantry: stovetop popcorn, crunchy with a smoky touch.\n\nINGREDIENTS (1 serving):\n- 30g popcorn kernels\n- 1 tablespoon olive oil (5g)\n- Salt and smoked paprika to taste\n\nPREPARATION:\n1. Heat the olive oil in a pot with a lid.\n2. Add the kernels and cover.\n3. Shake the pot until the popping stops.\n\nTO SERVE:\n1. Transfer to a large bowl.\n2. Season with salt and paprika and toss well.\n\nLIFE''S TIP: Stovetop popcorn is fiber and volume. Very different from raiding the chips.", "es": "SOBRE EL PLATO: Para el hambre de maratón de series sin asaltar la despensa: palomitas de olla, crujientes y con un toque ahumado.\n\nINGREDIENTES (1 porción):\n- 30g de maíz para palomitas\n- 1 cucharada de aceite de oliva (5g)\n- Sal y pimentón ahumado a gusto\n\nPREPARACIÓN:\n1. Calienta el aceite en una olla con tapa.\n2. Añade el maíz y tapa.\n3. Agita la olla hasta que dejen de estallar.\n\nMONTAJE:\n1. Pásalas a un tazón grande.\n2. Sazona con sal y pimentón y mezcla bien.\n\nCONSEJO DE LIFE: Las palomitas de olla son fibra y volumen. Muy distinto a atacar las papas fritas de bolsa."}'::jsonb
where id = '6eb7833d-af78-4f97-b860-c59a2b3e63c5';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Crispy Rosemary Sweet Potato Chips", "subtitulo": "Instead of bagged chips"}, "es": {"titulo": "Chips Crujientes de Batata con Romero", "subtitulo": "En lugar de las papas de bolsa"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: The crunch of chips, without the list of unpronounceable ingredients. Thin sweet potato with rosemary.\n\nINGREDIENTS (1 serving):\n- 1 medium sweet potato, thinly sliced\n- 1 tablespoon olive oil (5g)\n- Salt and rosemary\n\nPREPARATION:\n1. Preheat the oven to 200°C (400°F).\n2. Slice the potato very thin (a mandoline helps).\n3. Toss with the olive oil, salt and rosemary.\n4. Spread on a baking sheet without overlapping and bake for 20 to 25 minutes, flipping halfway.\n\nTO SERVE:\n1. Let them cool for 5 minutes — that''s when they get crispy.\n2. Serve in a bowl.\n\nLIFE''S TIP: Swapping the bag for this, even once, is already a win. Keep stacking them up.", "es": "SOBRE EL PLATO: Lo crujiente de las papas de bolsa, sin la lista de ingredientes impronunciables. Batata finita con romero.\n\nINGREDIENTES (1 porción):\n- 1 batata mediana en rodajas finas\n- 1 cucharada de aceite de oliva (5g)\n- Sal y romero\n\nPREPARACIÓN:\n1. Precalienta el horno a 200°C.\n2. Corta la batata muy fina (una mandolina ayuda).\n3. Mezcla con el aceite, la sal y el romero.\n4. Extiende en una bandeja sin superponer y hornea de 20 a 25 minutos, dando vuelta a mitad de tiempo.\n\nMONTAJE:\n1. Deja enfriar 5 minutos — ahí es cuando quedan crujientes.\n2. Sirve en un tazón.\n\nCONSEJO DE LIFE: Cambiar la bolsa por esto, aunque sea una vez, ya es una victoria. Ve sumando."}'::jsonb
where id = 'dedb54b4-8b98-4cbd-9c83-e4ed0f93a47c';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Creamy Iced Coffee with Whey", "subtitulo": "Instead of energy drinks or soda"}, "es": {"titulo": "Café Helado Cremoso con Whey", "subtitulo": "En lugar de la bebida energética o el refresco"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: The energy you were looking for in an energy drink, now with protein and without the sugar bomb. Cold and creamy.\n\nINGREDIENTS (1 serving):\n- 1 cup cold coffee\n- 1 scoop whey (30g)\n- 100ml milk or plant-based drink\n- Ice and cinnamon\n\nPREPARATION:\n1. Brew the coffee and let it cool (or use what''s left from the day).\n2. Blend the coffee, whey and milk.\n3. Add the ice and blend again until frothy.\n\nTO SERVE:\n1. Serve in a tall glass.\n2. Sprinkle cinnamon on top.\n\nLIFE''S TIP: That 3 p.m. slump doesn''t need to be fixed with a can. This one lifts you up without the crash afterwards.", "es": "SOBRE EL PLATO: La energía que buscabas en la bebida energética, ahora con proteína y sin la bomba de azúcar. Frío y cremoso.\n\nINGREDIENTES (1 porción):\n- 1 taza de café frío\n- 1 scoop de whey (30g)\n- 100ml de leche o bebida vegetal\n- Hielo y canela\n\nPREPARACIÓN:\n1. Prepara el café y déjalo enfriar (o usa el que sobró del día).\n2. Licúa el café, el whey y la leche.\n3. Añade el hielo y licúa de nuevo hasta que haga espuma.\n\nMONTAJE:\n1. Sirve en un vaso alto.\n2. Espolvorea canela por encima.\n\nCONSEJO DE LIFE: Ese bajón de las 15 h no tiene que resolverse con una lata. Este te levanta sin el bajón después."}'::jsonb
where id = '3feb60ba-67aa-41e3-8b82-3aae5fcd9046';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Banana Oat Post-Workout Shake", "subtitulo": "Protein and carbs after training"}, "es": {"titulo": "Batido Post-Entreno de Plátano y Avena", "subtitulo": "Proteína y carbohidratos después de entrenar"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: After training your body asks for protein and carbs. This shake delivers both, creamy and fast.\n\nINGREDIENTS (1 serving):\n- 1 scoop whey (30g)\n- 1 banana\n- 200ml milk or plant-based drink\n- 30g oats\n- Ice\n\nPREPARATION:\n1. Put everything in the blender.\n2. Blend until smooth.\n\nTO SERVE:\n1. Serve in a large glass.\n2. Drink it right after your workout.\n\nLIFE''S TIP: Keep the banana frozen and take the shake in a bottle: you leave the gym and it''s ready.", "es": "SOBRE EL PLATO: Después de entrenar el cuerpo pide proteína y carbohidratos. Este batido entrega los dos, cremoso y rápido.\n\nINGREDIENTES (1 porción):\n- 1 scoop de whey (30g)\n- 1 plátano\n- 200ml de leche o bebida vegetal\n- 30g de avena\n- Hielo\n\nPREPARACIÓN:\n1. Pon todo en la licuadora.\n2. Licúa hasta que quede homogéneo.\n\nMONTAJE:\n1. Sirve en un vaso grande.\n2. Tómalo justo después de entrenar.\n\nCONSEJO DE LIFE: Deja el plátano congelado y lleva el batido en una botella: sales del entreno y ya está listo."}'::jsonb
where id = '6dd5ba00-c1bb-4ec9-a0e6-4e7013855936';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Green Apple & Ginger Juice", "subtitulo": "Light, refreshing and full of fiber"}, "es": {"titulo": "Jugo Verde de Manzana y Jengibre", "subtitulo": "Ligero, refrescante y lleno de fibra"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: Kale, green apple and ginger blended with coconut water. Light, refreshing and an easy way to get greens into your day.\n\nINGREDIENTS (1 serving):\n- 1 handful of kale or spinach\n- 1/2 green apple\n- Juice of 1/2 lemon\n- 200ml coconut water\n- Ginger and ice\n\nPREPARATION:\n1. Wash the greens well and cut the apple into pieces.\n2. Put everything in the blender.\n3. Blend well until the greens dissolve.\n\nTO SERVE:\n1. Serve in a glass with ice.\n2. Drink it right away, before it oxidizes.\n\nLIFE''S TIP: Don''t strain it. The kale fiber is half the point.", "es": "SOBRE EL PLATO: Col rizada, manzana verde y jengibre licuados con agua de coco. Ligero, refrescante y una forma fácil de sumar hojas verdes al día.\n\nINGREDIENTES (1 porción):\n- 1 puñado de col rizada o espinaca\n- 1/2 manzana verde\n- Jugo de 1/2 limón\n- 200ml de agua de coco\n- Jengibre y hielo\n\nPREPARACIÓN:\n1. Lava bien las hojas y corta la manzana en trozos.\n2. Pon todo en la licuadora.\n3. Licúa bien hasta deshacer las hojas.\n\nMONTAJE:\n1. Sirve en un vaso con hielo.\n2. Tómalo al momento, antes de que se oxide.\n\nCONSEJO DE LIFE: No lo cueles. La fibra de la col es la mitad de la gracia."}'::jsonb
where id = '0c126771-bd06-4a93-a8c4-534374a5bdfa';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Banana Protein Smoothie", "subtitulo": "Simple, creamy and filling"}, "es": {"titulo": "Licuado Proteico de Plátano", "subtitulo": "Simple, cremoso y saciante"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: A liquid breakfast for people with no time: banana, whey and oats blended until creamy.\n\nINGREDIENTS (1 serving):\n- 1 banana\n- 1 scoop whey (30g)\n- 200ml milk or plant-based drink\n- 1 tablespoon oats\n- Cinnamon\n\nPREPARATION:\n1. Put everything in the blender.\n2. Blend until creamy.\n\nTO SERVE:\n1. Serve in a glass.\n2. Sprinkle cinnamon on top.\n\nLIFE''S TIP: Freeze the banana in slices the night before. The smoothie turns out like a milkshake.", "es": "SOBRE EL PLATO: Un desayuno líquido para quien no tiene tiempo: plátano, whey y avena licuados hasta quedar cremosos.\n\nINGREDIENTES (1 porción):\n- 1 plátano\n- 1 scoop de whey (30g)\n- 200ml de leche o bebida vegetal\n- 1 cucharada de avena\n- Canela\n\nPREPARACIÓN:\n1. Pon todo en la licuadora.\n2. Licúa hasta que quede cremoso.\n\nMONTAJE:\n1. Sirve en un vaso.\n2. Espolvorea canela por encima.\n\nCONSEJO DE LIFE: Congela el plátano en rodajas la noche anterior. El licuado queda como un milkshake."}'::jsonb
where id = '589625d3-204e-418c-b3e5-b5d031722be0';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Healthy Strawberry Milkshake", "subtitulo": "Tasty like dessert, light like a snack"}, "es": {"titulo": "Milkshake Fit de Fresa", "subtitulo": "Rico como postre, ligero como merienda"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: Milkshake flavor without going off track: strawberry, whey and yogurt. Kills the sweet craving with protein.\n\nINGREDIENTS (1 serving):\n- 100g strawberries (fresh or frozen)\n- 1 scoop whey (30g)\n- 150ml milk or plant-based drink\n- 2 tablespoons plain yogurt\n- Ice\n\nPREPARATION:\n1. Put everything in the blender.\n2. Blend until creamy.\n\nTO SERVE:\n1. Serve in a well-chilled glass.\n2. Garnish with a sliced strawberry on the rim.\n\nLIFE''S TIP: Frozen strawberries replace the ice and make it thicker.", "es": "SOBRE EL PLATO: Sabor a milkshake sin salirte del plan: fresa, whey y yogur. Calma el antojo dulce con proteína.\n\nINGREDIENTES (1 porción):\n- 100g de fresas (frescas o congeladas)\n- 1 scoop de whey (30g)\n- 150ml de leche o bebida vegetal\n- 2 cucharadas de yogur natural\n- Hielo\n\nPREPARACIÓN:\n1. Pon todo en la licuadora.\n2. Licúa hasta que quede cremoso.\n\nMONTAJE:\n1. Sirve en un vaso bien frío.\n2. Decora con una fresa cortada en el borde.\n\nCONSEJO DE LIFE: La fresa congelada reemplaza el hielo y lo deja más espeso."}'::jsonb
where id = 'e514cd6d-eb4b-498f-bbf8-88d5848d4fe1';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Calming Chamomile & Lemon Balm Tea", "subtitulo": "A warm ritual to end the day"}, "es": {"titulo": "Té Calmante de Manzanilla y Melisa", "subtitulo": "Un ritual caliente para cerrar el día"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: Chamomile and lemon balm in a hot cup: a ritual to slow down before bed.\n\nINGREDIENTS (1 cup):\n- 1 tablespoon dried chamomile\n- 1 tablespoon lemon balm\n- 200ml hot water\n- Honey to taste (optional)\n\nPREPARATION:\n1. Boil the water and turn off the heat.\n2. Add the herbs and cover.\n3. Let it steep for 5 minutes.\n\nTO SERVE:\n1. Strain straight into the cup.\n2. Sweeten with honey, if you like.\n\nLIFE''S TIP: Drink it slowly, away from screens. Half the effect is the ritual.", "es": "SOBRE EL PLATO: Manzanilla y melisa en una taza caliente: un ritual para bajar las revoluciones antes de dormir.\n\nINGREDIENTES (1 taza):\n- 1 cucharada de manzanilla seca\n- 1 cucharada de melisa\n- 200ml de agua caliente\n- Miel a gusto (opcional)\n\nPREPARACIÓN:\n1. Hierve el agua y apaga el fuego.\n2. Añade las hierbas y tapa.\n3. Deja en infusión 5 minutos.\n\nMONTAJE:\n1. Cuela directo en la taza.\n2. Endulza con miel, si quieres.\n\nCONSEJO DE LIFE: Tómalo sin prisa, lejos de la pantalla. La mitad del efecto es el ritual."}'::jsonb
where id = 'ae1816b1-d2e0-4cdc-bd76-dbbeaac1bddf';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Green Tea with Lemon", "subtitulo": "Light and refreshing for mid-morning"}, "es": {"titulo": "Té Verde con Limón", "subtitulo": "Ligero y refrescante para media mañana"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: Green tea brewed just right, not bitter, with a touch of lemon. Light and great for mid-morning.\n\nINGREDIENTS (1 cup):\n- 1 teaspoon green tea\n- 200ml water at 80°C (175°F)\n- A slice of lemon\n\nPREPARATION:\n1. Heat the water until small bubbles start to form, without boiling.\n2. Add the tea and let it steep for 3 minutes.\n\nTO SERVE:\n1. Strain into the cup.\n2. Finish with the lemon slice.\n\nLIFE''S TIP: Boiling water burns green tea and makes it bitter. 80°C (175°F) is the sweet spot.", "es": "SOBRE EL PLATO: Té verde en su punto, sin amargar, con un toque de limón. Ligero y bueno para media mañana.\n\nINGREDIENTES (1 taza):\n- 1 cucharadita de té verde\n- 200ml de agua a 80°C\n- Una rodaja de limón\n\nPREPARACIÓN:\n1. Calienta el agua hasta que empiecen a formarse burbujitas, sin hervir.\n2. Añade el té y deja reposar 3 minutos.\n\nMONTAJE:\n1. Cuela en la taza.\n2. Termina con la rodaja de limón.\n\nCONSEJO DE LIFE: El agua hirviendo quema el té verde y lo amarga. 80°C es el punto."}'::jsonb
where id = '5024d2d8-65e2-4c64-b189-a796d7a03d54';
update public.receitas_cozinha set
  traducoes = '{"en": {"titulo": "Ginger, Lemon & Honey Tea", "subtitulo": "Hot, citrusy and comforting"}, "es": {"titulo": "Té de Jengibre, Limón y Miel", "subtitulo": "Caliente, cítrico y reconfortante"}}'::jsonb,
  conteudo_traducoes = '{"en": "ABOUT THE DISH: Boiled ginger, lemon and a drizzle of honey: it warms you up and feels like self-care.\n\nINGREDIENTS (1 cup):\n- 3 slices of ginger\n- Juice of 1/2 lemon\n- 200ml water\n- Honey to taste\n\nPREPARATION:\n1. Boil the water with the ginger for 5 minutes.\n2. Turn off the heat and add the lemon.\n\nTO SERVE:\n1. Serve in the cup with the ginger slices.\n2. Sweeten with honey, if you like.\n\nLIFE''S TIP: After a heavy meal, this warm tea goes down really well.", "es": "SOBRE EL PLATO: Jengibre hervido, limón y un chorrito de miel: calienta y da esa sensación de cuidado.\n\nINGREDIENTES (1 taza):\n- 3 rodajas de jengibre\n- Jugo de 1/2 limón\n- 200ml de agua\n- Miel a gusto\n\nPREPARACIÓN:\n1. Hierve el agua con el jengibre 5 minutos.\n2. Apaga el fuego y añade el limón.\n\nMONTAJE:\n1. Sirve en la taza con las rodajas de jengibre.\n2. Endulza con miel, si quieres.\n\nCONSEJO DE LIFE: Después de una comida pesada, este té calentito cae muy bien."}'::jsonb
where id = 'cb666433-f034-4f40-a54f-056d6fb5ff50';

-- 3b. RPC com idioma. Sem argumento continua devolvendo pt (app antigo).
drop function if exists public.receitas_conteudo_liberado();
create or replace function public.receitas_conteudo_liberado(p_idioma text default 'pt-BR')
returns table(id uuid, conteudo text)
language sql
stable security definer
set search_path to 'public'
as $function$
  select r.id,
         coalesce(
           case when p_idioma in ('en', 'es') then r.conteudo_traducoes ->> p_idioma end,
           r.conteudo
         )
  from public.receitas_cozinha r
  where auth.uid() is not null
    and (not coalesce(r.premium, false) or public.is_premium_like(auth.uid()));
$function$;
revoke all on function public.receitas_conteudo_liberado(text) from public, anon;
grant execute on function public.receitas_conteudo_liberado(text) to authenticated, service_role;

